// ELEMENTS (ecrã inteiro):
// 1. Navy liso com grão e vinheta
// 2. Eyebrow + título em Cormorant (*palavras* em itálico ciano)
// 3. Árvore de equipa: "Tu" (coral) → 3 consultores (contorno ciano) em l2At → 6 em l3At, linhas a desenhar-se
// 4. A partir de coinAt, pontos coral sobem pelas linhas até ao "Tu" (ganhos da equipa) e o "Tu" pulsa
// 5. Legenda (caption) em Cormorant em captionAt
import React, { useId } from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import { FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const NAVY = "#0E1626";
const CYAN = "#05B8E6";
const CORAL = "#F06052";
const WHITE = "#F4F1EA";
const EASE = Easing.bezier(0.25, 0.1, 0.25, 1);
const BACK = Easing.out(Easing.back(1.8));
const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const Grain: React.FC<{ f: number }> = ({ f }) => {
  const id = useId().replace(/:/g, "");
  return (
    <AbsoluteFill style={{ pointerEvents: "none" }}>
      <AbsoluteFill style={{ background: "radial-gradient(ellipse at 50% 50%, rgba(0,0,0,0) 55%, rgba(0,0,0,0.3) 100%)" }} />
      <svg width="100%" height="100%" style={{ position: "absolute", inset: 0, opacity: 0.1, mixBlendMode: "overlay" }}>
        <filter id={id}>
          <feTurbulence type="fractalNoise" baseFrequency="0.85" numOctaves={2} seed={f % 12} />
          <feColorMatrix type="saturate" values="0" />
        </filter>
        <rect width="100%" height="100%" filter={`url(#${id})`} />
      </svg>
    </AbsoluteFill>
  );
};

const Person: React.FC<{ r: number; color: string }> = ({ r, color }) => (
  <>
    <circle cy={-r * 0.22} r={r * 0.24} fill={color} />
    <path d={`M${-r * 0.48} ${r * 0.5} Q0 ${-r * 0.08} ${r * 0.48} ${r * 0.5}`} fill={color} />
  </>
);

const IadEquipa: React.FC<PrimitiveProps> = ({ anim, fps, format, frame: box }) => {
  const f = useCurrentFrame();
  const W = box.width;
  const H = box.height;
  const u = format === "landscape" ? H / 1080 : format === "half" ? (H / 960) * 0.85 : W / 1080;
  const p = (anim.params ?? {}) as Record<string, unknown>;
  const eyebrow = String(p.eyebrow ?? "").trim();
  const caption = String(p.caption ?? "").trim();
  const l2At = Number(p.l2At ?? 0.6);
  const l3At = Number(p.l3At ?? 1.8);
  const coinAt = Number(p.coinAt ?? 3.8);
  const captionAt = Number(p.captionAt ?? 4.4);
  const parts = String(anim.text ?? "").split(/(\*[^*]+\*)/).filter(Boolean);

  const show = (delay: number, len = 0.6, easing = EASE): number =>
    interpolate(f, [Math.round(delay * fps), Math.round((delay + len) * fps)], [0, 1], { ...clamp, easing });
  const t = f / fps;
  const cx = W / 2;
  const top = { x: cx, y: H * 0.36 };
  // Spaced so the six leaves never touch (leaf r = 48u, 140u apart at the closest).
  const l2 = [-1, 0, 1].map((k) => ({ x: cx + k * 330 * u, y: H * 0.53 }));
  const l3 = l2.flatMap((n) => [-1, 1].map((k) => ({ x: n.x + k * 95 * u, y: H * 0.68, parent: n })));
  const grow = (a: { x: number; y: number }, b: { x: number; y: number }, k: number) => ({ x: a.x + (b.x - a.x) * k, y: a.y + (b.y - a.y) * k });
  const flowing = t > coinAt;
  const pulse = flowing ? 1 + Math.max(0, Math.sin(t * 6)) * 0.06 : 1;

  return (
    <AbsoluteFill style={{ backgroundColor: NAVY, overflow: "hidden" }}>
      <div style={{ position: "absolute", top: (format === "half" ? 40 : 230) * u, left: 0, right: 0, display: "flex", flexDirection: "column", alignItems: "center", gap: 18 * u, textAlign: "center" }}>
        {eyebrow ? (
          <div style={{ display: "flex", alignItems: "center", gap: 16 * u, fontFamily: FONTS.body, fontWeight: 600, fontSize: 28 * u, letterSpacing: "0.3em", textTransform: "uppercase", color: WHITE, opacity: show(0.05) }}>
            <div style={{ width: 50 * u * show(0.05, 0.8), height: 3 * u, background: CYAN }} />
            {eyebrow}
          </div>
        ) : null}
        <div style={{ fontFamily: FONTS.display, fontWeight: 500, fontSize: 92 * u, lineHeight: 1, color: WHITE, whiteSpace: "nowrap", opacity: show(0.15), transform: `translateY(${(1 - show(0.15)) * 24 * u}px)` }}>
          {parts.map((s, i) => <span key={i} style={{ fontStyle: s.startsWith("*") ? "italic" : "normal", color: s.startsWith("*") ? CYAN : WHITE }}>{s.replace(/\*/g, "")}</span>)}
        </div>
      </div>
      <svg width={W} height={H} style={{ position: "absolute", inset: 0 }}>
        {l2.map((n, i) => {
          const e = grow(top, n, show(l2At + i * 0.12, 0.5));
          return <line key={`a${i}`} x1={top.x} y1={top.y} x2={e.x} y2={e.y} stroke={CYAN} strokeOpacity={0.6} strokeWidth={3 * u} />;
        })}
        {l3.map((n, i) => {
          const e = grow(n.parent, n, show(l3At + i * 0.08, 0.45));
          return <line key={`b${i}`} x1={n.parent.x} y1={n.parent.y} x2={e.x} y2={e.y} stroke={CYAN} strokeOpacity={0.45} strokeWidth={2.5 * u} />;
        })}
        {flowing ? [...l3.map((n) => [n, n.parent] as const), ...l2.map((n) => [n, top] as const)].map(([a, b], i) => {
          const ph = ((t - coinAt) * 0.9 + i * 0.17) % 1;
          const pt = grow(a, b, ph);
          return <circle key={`c${i}`} cx={pt.x} cy={pt.y} r={9 * u} fill={CORAL} opacity={Math.sin(ph * Math.PI)} />;
        }) : null}
        {l3.map((n, i) => (
          <g key={`n3${i}`} transform={`translate(${n.x} ${n.y}) scale(${show(l3At + 0.2 + i * 0.08, 0.45, BACK)})`}>
            <circle r={48 * u} fill={NAVY} stroke={CYAN} strokeWidth={2.5 * u} strokeOpacity={0.7} />
            <Person r={48 * u} color={WHITE} />
          </g>
        ))}
        {l2.map((n, i) => (
          <g key={`n2${i}`} transform={`translate(${n.x} ${n.y}) scale(${show(l2At + 0.25 + i * 0.12, 0.5, BACK)})`}>
            <circle r={66 * u} fill={NAVY} stroke={CYAN} strokeWidth={4 * u} />
            <Person r={66 * u} color={WHITE} />
          </g>
        ))}
        <g transform={`translate(${top.x} ${top.y}) scale(${show(0.2, 0.5, BACK) * pulse})`}>
          <circle r={110 * u} fill={CORAL} opacity={0.22} />
          <circle r={88 * u} fill={CORAL} />
          <text textAnchor="middle" dy={20 * u} style={{ fontFamily: FONTS.display, fontWeight: 600, fontSize: 64 * u }} fill={NAVY}>Tu</text>
        </g>
      </svg>
      {caption ? (
        <div style={{ position: "absolute", left: 80 * u, right: 80 * u, bottom: (format === "half" ? 24 : 300) * u, textAlign: "center", fontFamily: FONTS.display, fontWeight: 500, fontSize: (format === "half" ? 58 : 70) * u, lineHeight: 1.1, color: WHITE, opacity: show(captionAt, 0.7), transform: `translateY(${(1 - show(captionAt, 0.7)) * 24 * u}px)` }}>
          {caption}
          <div style={{ margin: `${24 * u}px auto 0`, width: 120 * u * show(captionAt + 0.3, 0.7), height: 3 * u, background: CYAN }} />
        </div>
      ) : null}
      <Grain f={f} />
    </AbsoluteFill>
  );
};

export default IadEquipa;
